<div class="table-responsive slaughter-table-wrap"><table class="enterprise-table" data-searchable="false" aria-label="Journal des mouvements de chambre froide"><thead><tr><th>Date</th><th>Article / lot</th><th>Mouvement</th><th>Référence</th><th>Entrée (kg)</th><th>Sortie (kg)</th><th>Réservé / libéré (kg)</th></tr></thead><tbody><?php foreach($report['journal'] as $m):?><tr><td><?=e(date('d/m/Y H:i',strtotime($m['created_at'])))?></td><td><strong><?=e($m['article'])?></strong><br><?=e($m['lot_number'])?></td><td><?=e($m['label'])?></td><td><?=e($m['reference'])?></td><td><?=$m['grams']>0?$kg($m['grams']):'—'?></td><td><?=$m['grams']<0?$kg(-$m['grams']):'—'?></td><td><?=$m['direction']==='reservation'?e(number_format((float)$m['quantity_kg'],3,',',' ')):'—'?></td></tr><?php endforeach;?></tbody></table></div>
